+package org.apache.dubbo.common.utils;
+
+import java.util.Iterator;
+import java.util.LinkedHashMap;
+import java.util.Map;
+import java.util.concurrent.locks.Lock;
+import java.util.concurrent.locks.ReentrantLock;
+
+/**
+ * Shared infrastructure for {@link LRUCache} and {@link LRU2Cache}: locking, capacity management,
+ * and the thread-safe overrides of {@link LinkedHashMap} that both caches require.
+ */
+abstract class AbstractLRUCache<K, V> extends LinkedHashMap<K, V> {
+
+    private static final long serialVersionUID = 1L;
+
+    static final float DEFAULT_LOAD_FACTOR = 0.75f;
+    static final int DEFAULT_MAX_CAPACITY = 1000;
+
+    protected final Lock lock = new ReentrantLock();
+    protected volatile int maxCapacity;
+
+    AbstractLRUCache(int maxCapacity) {
+        super(16, DEFAULT_LOAD_FACTOR, true);
+        this.maxCapacity = maxCapacity;
+    }
+
+    @Override
+    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
+        return size() > maxCapacity;
+    }
+
+    @Override
+    public boolean containsKey(Object key) {
+        lock.lock();
+        try {
+            return super.containsKey(key);
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    @Override
+    public V get(Object key) {
+        lock.lock();
+        try {
+            return super.get(key);
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    @Override
+    public int size() {
+        lock.lock();
+        try {
+            return super.size();
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    @Override
+    public void clear() {
+        lock.lock();
+        try {
+            onClear();
+            super.clear();
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    /** Hook called inside the lock during {@link #clear()}. Subclasses may clear auxiliary state here. */
+    protected void onClear() {}
+
+    public int getMaxCapacity() {
+        return maxCapacity;
+    }
+
+    public void setMaxCapacity(int maxCapacity) {
+        lock.lock();
+        try {
+            this.maxCapacity = maxCapacity;
+            onSetMaxCapacity(maxCapacity);
+            trimToSize();
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    /** Hook called inside the lock during {@link #setMaxCapacity(int)}. Subclasses may resize auxiliary state here. */
+    protected void onSetMaxCapacity(int newCapacity) {}
+
+    protected void trimToSize() {
+        while (super.size() > maxCapacity) {
+            Iterator<Map.Entry<K, V>> it = super.entrySet().iterator();
+            if (it.hasNext()) {
+                it.next();
+                it.remove();
+            }
+        }
+    }
+}
